-- grove-gmk3060l
do $charts$
declare v_type uuid; v_manu uuid; v_machine uuid; v_cfg uuid; v_src uuid; v_chart uuid;
begin
  select id into v_type from public.machine_types where code = 'grue_mobile';
  if v_type is null then raise exception 'type_code inconnu : grue_mobile'; end if;
  select id into v_manu from public.manufacturers where lower(name) = lower('Grove');
  if v_manu is null then raise exception 'constructeur inconnu : Grove'; end if;
  select id into v_src from public.chart_sources where owner_id is null and document_title = 'GMK3060L Product Guide 60 t 48 m 8,7 - 15 m 65 m (édition métrique, EN 13000)'
    and reference is not distinct from 'sha256:621f544c5bdf793443b26c37056c813547f8f4ef0663f4f2bdddb2edfa82bfde' and edition is not distinct from null;
  if v_src is null then
    values (null, 'GMK3060L Product Guide 60 t 48 m 8,7 - 15 m 65 m (édition métrique, EN 13000)', 'sha256:621f544c5bdf793443b26c37056c813547f8f4ef0663f4f2bdddb2edfa82bfde', null, 'https://www.manitowoc.com/media/14859/download', 'Manitowoc Cranes (constructeur Grove), fiche « GMK3060L Metric » sur manitowoc.com') returning id into v_src;
  else update public.chart_sources set url = 'https://www.manitowoc.com/media/14859/download', publisher = 'Manitowoc Cranes (constructeur Grove), fiche « GMK3060L Metric » sur manitowoc.com', updated_at = now() where id = v_src;
  end if;
  select id into v_machine from public.machines where owner_id is null and manufacturer_id = v_manu and lower(model) = lower('GMK3060L');
  if v_machine is null then
    values (v_type, v_manu, 'GMK3060L', null, '{"capacite_max_t":60,"fleche_principale_m":"9,6 - 48,0","fleche_fleche_m":"8,7 - 15","hauteur_max_pointe_fleche_m":51,"contrepoids_max_t":13.5}'::jsonb) returning id into v_machine;
  else update public.machines set type_id = v_type, specs = '{"capacite_max_t":60,"fleche_principale_m":"9,6 - 48,0","fleche_fleche_m":"8,7 - 15","hauteur_max_pointe_fleche_m":51,"contrepoids_max_t":13.5}'::jsonb, updated_at = now() where id = v_machine;
  end if;
  -- configuration fleche-principale-360-cw12-5t
  select id into v_cfg from public.machine_configurations where machine_id = v_machine and params->>'slug' = 'fleche-principale-360-cw12-5t';
  if v_cfg is null then
    values (v_machine, 'Flèche principale 9,6-48,0 m, calage 6,2 m, 360°, contrepoids 12,5 t', '{"contrepoids_t":12.5,"base_calage_m":6.2,"zone":"360°","flechette":false,"slug":"fleche-principale-360-cw12-5t"}'::jsonb, null, 'Tableau « Telescopic boom » p. 11 du document, 14 colonnes de longueur de flèche (9,55 à 48,0 m), 27 lignes de portée (3,0 à 42,0 m), toutes saisies ; cellules vides = vides dans le tableau. Capacité = charge utile + poids du crochet et du dispositif d''élingage (doc. p. 27) : moufle non déduite, masse non documentée (hook_block_mass_kg = null). Valable fléchette démontée (p. 27). Mouflage et conditions de vent non indiqués sur la page. Valeurs non monotones (capacité qui remonte quand la flèche s''allonge à certaines portées) reproduites telles quelles, présentes dans le tableau imprimé. Relecture avancée : diff intégral page 11, 378 cellules (dont cellules vides, en-têtes de flèche et portées), 0 écart (extraction pdfplumber par coordonnées de mots + pdftotext -layout + lecture visuelle du rendu PNG 150 dpi). | Pages : p. 9 : diagramme de levage, renvoi « * En arrière avec équipement supplémentaire » ; p. 10 : flèche télescopique, 360°, calage 6,2 m, contrepoids 13,5 t ; p. 11 : même tableau, 12,5 t ; p. 27 : « Les capacités de levage sont conformes à la norme EN 13000:2010 », capacités en tonnes, capacité = charge utile + crochet et élingage, flèche principale valable fléchette démontée') returning id into v_cfg;
  else update public.machine_configurations set label = 'Flèche principale 9,6-48,0 m, calage 6,2 m, 360°, contrepoids 12,5 t', params = '{"contrepoids_t":12.5,"base_calage_m":6.2,"zone":"360°","flechette":false,"slug":"fleche-principale-360-cw12-5t"}'::jsonb, hook_block_mass_kg = null, notes = 'Tableau « Telescopic boom » p. 11 du document, 14 colonnes de longueur de flèche (9,55 à 48,0 m), 27 lignes de portée (3,0 à 42,0 m), toutes saisies ; cellules vides = vides dans le tableau. Capacité = charge utile + poids du crochet et du dispositif d''élingage (doc. p. 27) : moufle non déduite, masse non documentée (hook_block_mass_kg = null). Valable fléchette démontée (p. 27). Mouflage et conditions de vent non indiqués sur la page. Valeurs non monotones (capacité qui remonte quand la flèche s''allonge à certaines portées) reproduites telles quelles, présentes dans le tableau imprimé. Relecture avancée : diff intégral page 11, 378 cellules (dont cellules vides, en-têtes de flèche et portées), 0 écart (extraction pdfplumber par coordonnées de mots + pdftotext -layout + lecture visuelle du rendu PNG 150 dpi). | Pages : p. 9 : diagramme de levage, renvoi « * En arrière avec équipement supplémentaire » ; p. 10 : flèche télescopique, 360°, calage 6,2 m, contrepoids 13,5 t ; p. 11 : même tableau, 12,5 t ; p. 27 : « Les capacités de levage sont conformes à la norme EN 13000:2010 », capacités en tonnes, capacité = charge utile + crochet et élingage, flèche principale valable fléchette démontée', updated_at = now() where id = v_cfg;
  end if;
  select id into v_chart from public.load_charts where configuration_id = v_cfg order by created_at limit 1;
  if v_chart is null then
    values (v_cfg, 'radius_m', 'boom_length_m', 'kg', 'EN 13000', false, false, 'a_verifier', v_src, null, '2026-10-11'::timestamptz) returning id into v_chart;
  else update public.load_charts set axis_y = 'boom_length_m', standard = 'EN 13000', deductions_included = false, interpolation_allowed = false,
    status = 'a_verifier', source_id = v_src, entered_by = null, entered_at = '2026-10-11'::timestamptz, verified_by = null, verified_at = null, updated_at = now() where id = v_chart;
  end if;
